<?php require_once __DIR__.'/../app/Security.php'; require_once __DIR__.'/../app/Database.php'; start_secure_session(); if(!ara_is_installed()){ $_SESSION['install_notice']='CMS belum di-install. Silakan jalankan install.php terlebih dahulu.'; header('Location: '.ara_app_base_path().'/install.php'); exit; } if(!empty($_SESSION['admin_id'])){header('Location:index.php');exit;} $err=''; $notice=$_GET['installed']??''; if($_SERVER['REQUEST_METHOD']==='POST'){ $st=Database::pdo()->prepare('SELECT * FROM admins WHERE username=?');$st->execute([trim($_POST['username']??'')]);$a=$st->fetch(); if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];header('Location:index.php');exit;} $err='Username atau password salah.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login</title><link rel="stylesheet" href="assets/admin.css"></head><body class="login"><form method="post"><h1>ARA CMS</h1><?php if($notice):?><p class="ok">Instalasi berhasil. Silakan login.</p><?php endif;?><?php if($err):?><p class="err"><?=e($err)?></p><?php endif;?><input name="username" placeholder="Username" required><input type="password" name="password" placeholder="Password" required><button>Login</button></form></body></html>
